"use client";

import { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import Modal from "./Modal";
import Input from "./ui/Input";
import SegmentedControl from "./ui/SegmentedControl";
import SearchSelect from "./ui/SearchSelect";
import {
    Cloud,
    HardDrive,
    MonitorCheck,
    Users,
    CheckCircle2,
    ArrowRight,
    ArrowLeft,
    DollarSign,
    Target,
    Calendar,
    Clock
} from "lucide-react";
import { cn } from "@/lib/utils";
import axios from "axios";
import { useSimulation } from "@/components/SimulationProvider";
import { calculateCommission } from "@/lib/rulesEngine";

const orderSchema = z.object({
    // Step 1
    productId: z.number().min(1, "Selecione um produto"),
    doc: z.string().min(11, "Documento inválido"),
    name: z.string().min(3, "Nome obrigatório"),
    email: z.string().email("E-mail inválido"),
    phone: z.string().min(10, "Telefone inválido"),
    // Step 2
    mediaType: z.string().min(1, "Selecione a mídia"),
    validity: z.string().min(1, "Selecione a validade"),
    videoConference: z.boolean(),
    appointmentDate: z.string().optional(),
    appointmentTime: z.string().optional(),
    // Step 3
    coupon: z.string().optional(),
});

type OrderFormData = z.infer<typeof orderSchema>;

interface OrderJourneyModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => void;
    products: any[];
}

export default function OrderJourneyModal({ isOpen, onClose, onSubmit, products }: OrderJourneyModalProps) {
    const { currentUser } = useSimulation();
    const [step, setStep] = useState(1);
    const [isConsulting, setIsConsulting] = useState(false);

    const {
        register,
        handleSubmit,
        watch,
        setValue,
        reset,
        formState: { errors, isValid }
    } = useForm<OrderFormData>({
        resolver: zodResolver(orderSchema),
        defaultValues: {
            productId: 0,
            doc: "",
            name: "",
            email: "",
            phone: "",
            mediaType: "Nuvem",
            validity: "12 Meses",
            videoConference: true,
            coupon: "",
        }
    });

    const selectedProductId = watch("productId");
    const selectedProduct = products.find(p => p.id === selectedProductId);
    const docValue = watch("doc");
    const videoConference = watch("videoConference");

    // Auto-fill logic
    useEffect(() => {
        const fetchCustomer = async () => {
            const cleanDoc = docValue.replace(/[^0-9]/g, '');
            if (cleanDoc.length === 11 || cleanDoc.length === 14) {
                setIsConsulting(true);
                try {
                    const { data } = await axios.get(`/api/consulta/clientes?doc=${cleanDoc}`);
                    setValue("name", data.name);
                    setValue("email", data.email);
                    setValue("phone", data.phone);
                } catch (e) {
                    // Not found or error, let user type
                } finally {
                    setIsConsulting(false);
                }
            }
        };

        const timer = setTimeout(fetchCustomer, 1000);
        return () => clearTimeout(timer);
    }, [docValue, setValue]);

    const handleNext = () => setStep(s => s + 1);
    const handleBack = () => setStep(s => s - 1);

    const renderStep1 = () => (
        <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-300">
            <div>
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-4">1. Escolha o Certificado</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {products.filter(p => !selectedProductId || p.id === selectedProductId || step === 1).map((product) => (
                        <button
                            key={product.id}
                            type="button"
                            onClick={() => setValue("productId", product.id)}
                            className={cn(
                                "p-5 rounded-[2rem] border-2 text-left transition-all relative group",
                                selectedProductId === product.id
                                    ? "border-primary bg-primary/5 shadow-xl shadow-primary/10"
                                    : "border-slate-100 dark:border-slate-800 hover:border-slate-200 dark:hover:border-slate-700 bg-white dark:bg-slate-900"
                            )}
                        >
                            <div className="flex items-center gap-4">
                                <div className={cn(
                                    "size-12 rounded-2xl flex items-center justify-center transition-colors",
                                    selectedProductId === product.id ? "bg-primary text-white" : "bg-slate-100 dark:bg-slate-800 text-slate-500"
                                )}>
                                    {product.type === "A1" ? <Cloud size={24} /> : <HardDrive size={24} />}
                                </div>
                                <div className="flex-1">
                                    <p className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-tight">{product.name}</p>
                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{product.category} • {product.type}</p>
                                </div>
                                {selectedProductId === product.id && <CheckCircle2 className="text-primary" size={20} />}
                            </div>
                        </button>
                    ))}
                </div>
            </div>

            <div className="space-y-4 pt-4 border-t border-slate-50 dark:border-slate-800/50">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">2. Dados do Cliente</h3>
                <Input
                    label="CPF ou CNPJ"
                    {...register("doc")}
                    error={errors.doc?.message}
                    placeholder="Busca automática..."
                    helpText={isConsulting ? "Buscando dados na base Delta..." : "Ao digitar, buscaremos os dados para você."}
                />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <Input label="Nome Titular" {...register("name")} error={errors.name?.message} />
                    <Input label="WhatsApp" {...register("phone")} error={errors.phone?.message} />
                </div>
                <Input label="E-mail de Cadastro" {...register("email")} error={errors.email?.message} />
            </div>
        </div>
    );

    const renderStep2 = () => (
        <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-300 text-slate-900 dark:text-slate-100 text-sm">
            <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-800">
                <div className="flex items-center gap-4 mb-6">
                    <div className="size-10 rounded-xl bg-indigo-500/10 text-indigo-500 flex items-center justify-center">
                        <MonitorCheck size={20} />
                    </div>
                    <div>
                        <h4 className="font-black uppercase tracking-tight">Formato da Emissão</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Configurações Técnicas CertControl</p>
                    </div>
                </div>

                <div className="space-y-6">
                    <SegmentedControl
                        label="Tipo de Mídia"
                        value={watch("mediaType")}
                        onChange={(v) => setValue("mediaType", v)}
                        options={[
                            { label: "Nuvem (A1)", value: "Nuvem" },
                            { label: "Token (A3)", value: "Token" },
                            { label: "Cartão (A3)", value: "Cartão" },
                        ]}
                    />

                    <SegmentedControl
                        label="Modalidade de Atendimento"
                        value={videoConference ? "video" : "presencial"}
                        onChange={(v) => setValue("videoConference", v === "video")}
                        options={[
                            { label: "Videoconferência", value: "video" },
                            { label: "Presencial (Delta Hub)", value: "presencial" },
                        ]}
                    />

                    {videoConference && (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-in zoom-in-95 duration-200">
                            <div className="space-y-1.5 flex flex-col group">
                                <label className="text-[12px] font-bold text-slate-700 dark:text-slate-200 tracking-tight flex items-center gap-2">
                                    <Calendar size={14} className="text-primary" /> Data Disponível
                                </label>
                                <input type="date" {...register("appointmentDate")} className="w-full px-4 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-xs" />
                            </div>
                            <div className="space-y-1.5 flex flex-col group">
                                <label className="text-[12px] font-bold text-slate-700 dark:text-slate-200 tracking-tight flex items-center gap-2">
                                    <Clock size={14} className="text-primary" /> Horário
                                </label>
                                <input type="time" {...register("appointmentTime")} className="w-full px-4 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-xs" />
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );

    const renderStep3 = () => (
        <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-300">
            <div className="bg-emerald-500/5 dark:bg-emerald-500/10 border-2 border-emerald-500/20 rounded-[2.5rem] p-8 relative overflow-hidden">
                <div className="relative z-10 flex flex-col items-center text-center">
                    <div className="size-16 rounded-3xl bg-emerald-500 text-white flex items-center justify-center mb-6 shadow-xl shadow-emerald-500/30">
                        <CheckCircle2 size={32} />
                    </div>
                    <h3 className="text-2xl font-black text-slate-900 dark:text-white mb-2 tracking-tight">Tudo pronto para finalizar!</h3>
                    <p className="text-sm text-slate-500 max-w-xs mx-auto mb-8">Revise seu ganho e emita o certificado com um clique.</p>

                    <div className="w-full max-w-sm bg-white dark:bg-slate-900 rounded-3xl border border-emerald-500/20 p-6 space-y-4">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">Produto Selecionado</span>
                            <span className="font-bold text-slate-900 dark:text-white">{selectedProduct?.name}</span>
                        </div>
                        <div className="h-px bg-slate-100 dark:bg-slate-800" />
                        <div className="flex justify-between items-center">
                            <div>
                                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Sua Comissão</p>
                                <p className="text-3xl font-black text-emerald-500">
                                    {selectedProduct?.commission.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-3xl border border-slate-100 dark:border-slate-800">
                <div className="flex items-center gap-4">
                    <div className="size-12 rounded-2xl bg-primary/10 text-primary flex items-center justify-center">
                        <Target size={24} />
                    </div>
                    <div>
                        <p className="text-xs font-bold text-slate-900 dark:text-white uppercase tracking-tight">Rumo ao próximo nível</p>
                        <p className="text-[11px] text-slate-500 italic">"Este pedido te deixará a apenas 3 vendas da meta de Prata!"</p>
                    </div>
                </div>
            </div>
        </div>
    );

    return (
        <Modal isOpen={isOpen} onClose={onClose} title="Jornada de Venda" width="lg">
            <div className="flex h-full min-h-[500px]">
                {/* Left Form Content */}
                <div className="flex-1 pr-0 md:pr-8">
                    {/* Stepper Indicator */}
                    <div className="flex gap-2 mb-8">
                        {[1, 2, 3].map((s) => (
                            <div
                                key={s}
                                className={cn(
                                    "h-1.5 flex-1 rounded-full transition-all duration-300",
                                    s === step ? "bg-primary scale-x-105" : s < step ? "bg-emerald-500" : "bg-slate-200 dark:bg-slate-800"
                                )}
                            />
                        ))}
                    </div>

                    <form className="pb-24">
                        {step === 1 && renderStep1()}
                        {step === 2 && renderStep2()}
                        {step === 3 && renderStep3()}
                    </form>

                    {/* Footer Actions */}
                    <div className="absolute bottom-0 left-0 w-full p-8 bg-gradient-to-t from-white dark:from-slate-900 via-white/95 dark:via-slate-900/95 to-transparent flex items-center justify-between border-t border-slate-50 dark:border-slate-800/50">
                        <button
                            type="button"
                            onClick={step === 1 ? onClose : handleBack}
                            className="px-6 py-3 rounded-2xl font-bold text-xs text-slate-500 hover:text-slate-800 dark:hover:text-slate-200 transition-all flex items-center gap-2"
                        >
                            {step === 1 ? "Cancelar" : <><ArrowLeft size={16} /> Voltar</>}
                        </button>

                        <button
                            type="button"
                            onClick={step === 3 ? handleSubmit(onSubmit) : handleNext}
                            disabled={step === 1 && (!selectedProductId || !watch("doc"))}
                            className={cn(
                                "bg-primary text-white px-10 py-4 rounded-[1.25rem] font-black text-sm shadow-xl transition-all flex items-center gap-3",
                                "hover:scale-[1.02] active:scale-95 disabled:opacity-50 disabled:scale-100",
                                step === 3 ? "shadow-primary/40 ring-4 ring-primary/20" : "shadow-primary/20"
                            )}
                        >
                            {step === 3 ? "Finalizar e Gerar Link" : "Próximo Passo"}
                            {step < 3 && <ArrowRight size={18} />}
                        </button>
                    </div>
                </div>

                {/* Right Sidebar - Commission Widget (Gamification) */}
                <div className="hidden lg:block w-72 bg-slate-50 dark:bg-slate-800/20 rounded-[2.5rem] p-8 border border-slate-100 dark:border-slate-800/50 self-start sticky top-0 group">
                    <div className="flex flex-col items-center text-center space-y-6">
                        <div className="size-16 rounded-3xl bg-white dark:bg-slate-900 shadow-xl shadow-slate-200/50 dark:shadow-none flex items-center justify-center text-emerald-500 animate-bounce duration-[3000ms]">
                            <DollarSign size={32} />
                        </div>
                        <div>
                            <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-1">Comissão Estimada</h4>
                            <p className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">
                                {selectedProduct ? selectedProduct.commission.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }) : "R$ 0,00"}
                            </p>
                        </div>

                        <div className="w-full h-px bg-slate-200 dark:bg-slate-800" />

                        <div className="w-full text-left space-y-4">
                            <div className="flex items-center gap-3">
                                <Users size={18} className="text-slate-400" />
                                <div>
                                    <p className="text-[9px] font-bold text-slate-400 uppercase">Vendedor Responsável</p>
                                    <p className="text-xs font-bold text-slate-700 dark:text-slate-300">{currentUser.name}</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-3">
                                <CheckCircle2 size={18} className="text-emerald-500" />
                                <div>
                                    <p className="text-[9px] font-bold text-emerald-400 uppercase">Origem Confirmada</p>
                                    <p className="text-xs font-bold text-slate-700 dark:text-slate-300">Venda Direta - Delta</p>
                                </div>
                            </div>
                        </div>

                        <div className="mt-8 p-4 bg-primary/10 rounded-2xl border border-primary/20 w-full">
                            <p className="text-[10px] font-bold text-primary italic leading-tight">
                                "Pedidos com agendamento integrado têm 75% mais chance de conclusão no primeiro mês."
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </Modal>
    );
}
